+// TestObserveFloorRestartsTheClockWhenTheFloorMoves: the trigger is
+// floor-stationary age, so an advancing floor — however slowly — is not a
+// stall, and re-observing the same floor must not restart the clock either.
+func TestObserveFloorRestartsTheClockWhenTheFloorMoves(t *testing.T) {
+	r, _ := newTestRetry(t, nil)
+	base := time.Now()
+	now := base
+	r.clock = func() time.Time { return now }
+
+	r.observeFloor(100, base)
+	now = base.Add(10 * time.Minute)
+	r.observeFloor(100, now) // same floor: the clock keeps running
+	if _, age, _ := r.FloorStationaryFor(); age != 10*time.Minute {
+		t.Fatalf("age after re-observing the same floor = %s, want 10m0s", age)
+	}
+
+	r.observeFloor(101, now) // floor advanced: clock restarts
+	floor, age, ok := r.FloorStationaryFor()
+	if !ok || floor != 101 || age != 0 {
+		t.Fatalf("after the floor moved: floor=%d age=%s ok=%v, want 101/0s/true", floor, age, ok)
+	}
+
+	// And the breaker is disarmed again for the new floor.
+	msg := deliveredMsg(102, 4)
+	if _, err := r.Settle(t.Context(), msg, "transient"); err != nil {
+		t.Fatalf("Settle: %v", err)
+	}
+	if msg.Acked {
+		t.Error("breaker fired against a floor that had just moved")
+	}
+}
