+// fakeDLQ records dead-letter captures, or fails them on demand so the
+// never-drop path can be exercised.
+type fakeDLQ struct {
+	mu   sync.Mutex
+	msgs []*nats.Msg
+	err  error
+}
+
+func (f *fakeDLQ) PublishMsg(_ context.Context, m *nats.Msg, _ ...jetstream.PublishOpt) (*jetstream.PubAck, error) {
+	f.mu.Lock()
