+		{"no dlq subject", func() RetryConfig { c := testRetryConfig(pub); c.DLQSubject = ""; return c }(), "DLQSubject"},
+		{"unlimited max deliver", func() RetryConfig {
+			c := testRetryConfig(pub)
+			c.Backoff.MaxDeliver = backoff.UnlimitedMaxDeliver
+			return c
+		}(), "MaxDeliver"},
+		{"term on exhaustion", func() RetryConfig {
+			c := testRetryConfig(pub)
+			c.Backoff.TermOnExhaustion = true
+			return c
+		}(), "TermOnExhaustion"},
+		{"zero nak delay", func() RetryConfig { c := testRetryConfig(pub); c.Backoff.NakDelay = 0; return c }(), "NakDelay"},
+		{"uncapped growth", func() RetryConfig {
+			c := testRetryConfig(pub)
+			c.Backoff.Factor = 2
+			return c
+		}(), "MaxDelay"},
+		{"rung longer than the breaker window", func() RetryConfig {
+			c := testRetryConfig(pub)
+			c.Backoff.NakDelay = 30 * time.Minute
+			return c
+		}(), "exceeds FloorAge"},
+		{"grown rung longer than the breaker window", func() RetryConfig {
+			c := testRetryConfig(pub)
+			c.Backoff.NakDelay = time.Minute
+			c.Backoff.Factor = 4
+			c.Backoff.MaxDelay = time.Hour
+			return c
+		}(), "exceeds FloorAge"},
+		{"poll slower than the breaker window", func() RetryConfig {
+			c := testRetryConfig(pub)
+			c.FloorPoll = 20 * time.Minute
+			return c
+		}(), "FloorPoll"},
+		{"negative poll", func() RetryConfig { c := testRetryConfig(pub); c.FloorPoll = -time.Second; return c }(), "FloorPoll"},
+		{"negative min deliveries", func() RetryConfig {
+			c := testRetryConfig(pub)
+			c.MinDeliveries = -1
+			return c
+		}(), "MinDeliveries"},
+		{"min deliveries past the cap", func() RetryConfig {
+			c := testRetryConfig(pub)
+			c.MinDeliveries = 9
+			return c
+		}(), "MinDeliveries"},
+	}
+	for _, tt := range tests {
+		t.Run(tt.name, func(t *testing.T) {
