+}
+
+// TestSettleBreakerDeadLettersTheFloorBlocker is the ENT-1535 remedy: the
+// blocker at floor+1, on a floor stationary past the threshold, is captured
+// and Acked at delivery 2 — nowhere near the delivery cap that would
+// otherwise take ~43 minutes to reach.
+func TestSettleBreakerDeadLettersTheFloorBlocker(t *testing.T) {
+	var got Settlement
+	r, pub := newTestRetry(t, func(c *RetryConfig) {
+		c.OnSettle = func(_ context.Context, _ jetstream.Msg, s Settlement) { got = s }
+	})
+	armFloor(r, 2774436, 16*time.Minute)
+	msg := deliveredMsg(2774437, 2)
