  1	package jsconsumer
  2	
  3	import (
  4		"context"
  5		"errors"
  6		"log/slog"
  7		"slices"
  8		"strings"
  9		"sync"
 10		"testing"
 11		"time"
 12	
 13		"github.com/nats-io/nats.go"
 14		"github.com/nats-io/nats.go/jetstream"
 15		"go.opentelemetry.io/otel/trace"
 16	
 17		"github.com/entireio/go-nuts/backoff"
 18		"github.com/entireio/go-nuts/natsmsg"
 19		"github.com/entireio/go-nuts/natsmsg/natsmsgtest"
 20	)
 21	
 22	// fakeDLQ records dead-letter captures, or fails them on demand so the
 23	// never-drop path can be exercised.
 24	type fakeDLQ struct {
 25		mu   sync.Mutex
 26		msgs []*nats.Msg
 27		err  error
 28	}
 29	
 30	func (f *fakeDLQ) PublishMsg(_ context.Context, m *nats.Msg, _ ...jetstream.PublishOpt) (*jetstream.PubAck, error) {
 31		f.mu.Lock()
 32		defer f.mu.Unlock()
 33		if f.err != nil {
 34			return nil, f.err
 35		}
 36		f.msgs = append(f.msgs, m)
 37		return &jetstream.PubAck{Stream: "repo_refs_dlq_v1", Sequence: uint64(len(f.msgs))}, nil
 38	}
 39	
 40	func (f *fakeDLQ) captured() []*nats.Msg {
 41		f.mu.Lock()
 42		defer f.mu.Unlock()
 43		return append([]*nats.Msg(nil), f.msgs...)
 44	}
 45	
 46	var _ natsmsg.DLQPublisher = (*fakeDLQ)(nil)
 47	
 48	// testRetryConfig is the shape of the first adopter's config
 49	// (search-indexer-refs): a flat 5-minute rung well under the 15-minute
 50	// breaker threshold, MaxDeliver 5, capture to the ref-event DLQ.
 51	func testRetryConfig(pub natsmsg.DLQPublisher) RetryConfig {
 52		return RetryConfig{
 53			Backoff:    backoff.Policy{NakDelay: 5 * time.Minute, MaxDeliver: 5},
 54			DLQSubject: "repo.refs.dlq",
 55			Publisher:  pub,
 56			Name:       "search-indexer-refs",
 57		}
 58	}
 59	
 60	func newTestRetry(t *testing.T, mutate func(*RetryConfig)) (*Retry, *fakeDLQ) {
 61		t.Helper()
 62		pub := &fakeDLQ{}
 63		cfg := testRetryConfig(pub)
 64		if mutate != nil {
 65			mutate(&cfg)
 66		}
 67		r, err := NewRetry(cfg)
 68		if err != nil {
 69			t.Fatalf("NewRetry: %v", err)
 70		}
 71		return r, pub
 72	}
 73	
 74	// armFloor pins the Retry's observed ack floor at seq and freezes its clock
 75	// so the floor reads as stationary for age — the state the poll loop would
 76	// have built up over a real stall.
 77	func armFloor(r *Retry, seq uint64, age time.Duration) {
 78		now := time.Now()
 79		r.clock = func() time.Time { return now }
 80		r.observeFloor(seq, now.Add(-age))
 81	}
 82	
 83	// deliveredMsg is a message at stream sequence seq on its nth delivery.
 84	func deliveredMsg(seq uint64, n int) *natsmsgtest.FakeMsg {
 85		return &natsmsgtest.FakeMsg{
 86			SubjectVal: "repo.refs.update",
 87			DataVal:    []byte("ref-event"),
 88			HeadersVal: nats.Header{"X-Entire-Repo": []string{"01KWHDFJ0C575CRVF18DPVSQW0"}},
 89			Meta: &jetstream.MsgMetadata{
 90				Sequence:     jetstream.SequencePair{Stream: seq, Consumer: seq},
 91				NumDelivered: uint64(n),
 92			},
 93		}
 94	}
 95	
 96	// TestNewRetryRejectsUnworkableConfig: every rejection here is a
 97	// configuration that would otherwise start, read as configured, and quietly
 98	// not do what it says — the ENT-1535 failure mode, one level up.
 99	func TestNewRetryRejectsUnworkableConfig(t *testing.T) {
100		pub := &fakeDLQ{}
101		tests := []struct {
102			name string
103			cfg  RetryConfig
104			want string
105		}{
106			{"no publisher", func() RetryConfig { c := testRetryConfig(pub); c.Publisher = nil; return c }(), "Publisher"},
107			{"no dlq subject", func() RetryConfig { c := testRetryConfig(pub); c.DLQSubject = ""; return c }(), "DLQSubject"},
108			{"unlimited max deliver", func() RetryConfig {
109				c := testRetryConfig(pub)
110				c.Backoff.MaxDeliver = backoff.UnlimitedMaxDeliver
111				return c
112			}(), "MaxDeliver"},
113			{"term on exhaustion", func() RetryConfig {
114				c := testRetryConfig(pub)
115				c.Backoff.TermOnExhaustion = true
116				return c
117			}(), "TermOnExhaustion"},
118			{"zero nak delay", func() RetryConfig { c := testRetryConfig(pub); c.Backoff.NakDelay = 0; return c }(), "NakDelay"},
119			{"uncapped growth", func() RetryConfig {
120				c := testRetryConfig(pub)
121				c.Backoff.Factor = 2
122				return c
123			}(), "MaxDelay"},
124			{"rung longer than the breaker window", func() RetryConfig {
125				c := testRetryConfig(pub)
126				c.Backoff.NakDelay = 30 * time.Minute
127				return c
128			}(), "exceeds FloorAge"},
129			{"grown rung longer than the breaker window", func() RetryConfig {
130				c := testRetryConfig(pub)
131				c.Backoff.NakDelay = time.Minute
132				c.Backoff.Factor = 4
133				c.Backoff.MaxDelay = time.Hour
134				return c
135			}(), "exceeds FloorAge"},
136			{"poll slower than the breaker window", func() RetryConfig {
137				c := testRetryConfig(pub)
138				c.FloorPoll = 20 * time.Minute
139				return c
140			}(), "FloorPoll"},
141			{"negative poll", func() RetryConfig { c := testRetryConfig(pub); c.FloorPoll = -time.Second; return c }(), "FloorPoll"},
142			{"negative min deliveries", func() RetryConfig {
143				c := testRetryConfig(pub)
144				c.MinDeliveries = -1
145				return c
146			}(), "MinDeliveries"},
147			{"min deliveries past the cap", func() RetryConfig {
148				c := testRetryConfig(pub)
149				c.MinDeliveries = 9
150				return c
151			}(), "MinDeliveries"},
152		}
153		for _, tt := range tests {
154			t.Run(tt.name, func(t *testing.T) {
155				_, err := NewRetry(tt.cfg)
156				if err == nil || !strings.Contains(err.Error(), tt.want) {
157					t.Fatalf("NewRetry() err = %v, want error containing %q", err, tt.want)
158				}
159			})
160		}
