316	// TestSettleReportsAnUnidentifiableBlocker: the breaker identifies the
317	// blocker as the sequence immediately above the floor, which assumes the
318	// consumer's filter is dense enough for that message to exist. When it isn't
319	// — a narrow filter over a sparse stream — the breaker cannot fire, and that
320	// must not be silent: the log names the sequence it wanted against the one it
321	// saw, which is how a staging exercise tells "wrong predicate" apart from
322	// "the real blocker is on another replica".
323	func TestSettleReportsAnUnidentifiableBlocker(t *testing.T) {
