    22	// fakeDLQ records dead-letter captures, or fails them on demand so the
    23	// never-drop path can be exercised.
    24	type fakeDLQ struct {
    25		mu   sync.Mutex
    26		msgs []*nats.Msg
    27		err  error
    28	}
    29	
    30	func (f *fakeDLQ) PublishMsg(_ context.Context, m *nats.Msg, _ ...jetstream.PublishOpt) (*jetstream.PubAck, error) {
    31		f.mu.Lock()
    32		defer f.mu.Unlock()
    33		if f.err != nil {
    34			return nil, f.err
    35		}
    36		f.msgs = append(f.msgs, m)
    37		return &jetstream.PubAck{Stream: "repo_refs_dlq_v1", Sequence: uint64(len(f.msgs))}, nil
    38	}
    39	
    40	func (f *fakeDLQ) captured() []*nats.Msg {
    41		f.mu.Lock()
    42		defer f.mu.Unlock()
    43		return append([]*nats.Msg(nil), f.msgs...)
    44	}
    45	
    46	var _ natsmsg.DLQPublisher = (*fakeDLQ)(nil)
