    48	// testRetryConfig is the shape of the first adopter's config
    49	// (search-indexer-refs): a flat 5-minute rung well under the 15-minute
    50	// breaker threshold, MaxDeliver 5, capture to the ref-event DLQ.
    51	func testRetryConfig(pub natsmsg.DLQPublisher) RetryConfig {
    52		return RetryConfig{
    53			Backoff:    backoff.Policy{NakDelay: 5 * time.Minute, MaxDeliver: 5},
    54			DLQSubject: "repo.refs.dlq",
    55			Publisher:  pub,
    56			Name:       "search-indexer-refs",
    57		}
    58	}
    59	
    60	func newTestRetry(t *testing.T, mutate func(*RetryConfig)) (*Retry, *fakeDLQ) {
    61		t.Helper()
    62		pub := &fakeDLQ{}
    63		cfg := testRetryConfig(pub)
    64		if mutate != nil {
    65			mutate(&cfg)
    66		}
    67		r, err := NewRetry(cfg)
    68		if err != nil {
    69			t.Fatalf("NewRetry: %v", err)
    70		}
    71		return r, pub
    72	}
