   163	// TestNewRetryDefaults: the zero values are the sized ones from ENT-1535's
   164	// forensics, and a rung longer than FloorAge is legal once the breaker is
   165	// explicitly disabled.
   166	func TestNewRetryDefaults(t *testing.T) {
   167		r, _ := newTestRetry(t, nil)
   168		if r.cfg.FloorAge != DefaultFloorAge {
   169			t.Errorf("FloorAge = %s, want %s", r.cfg.FloorAge, DefaultFloorAge)
   170		}
   171		if r.cfg.MinDeliveries != DefaultMinDeliveries {
   172			t.Errorf("MinDeliveries = %d, want %d", r.cfg.MinDeliveries, DefaultMinDeliveries)
   173		}
   174		// FloorAge/10 is 90s, clamped to the 30s ceiling.
   175		if got := r.pollInterval(); got != maxFloorPoll {
   176			t.Errorf("pollInterval = %s, want %s", got, maxFloorPoll)
   177		}
   178		if !r.breakerEnabled() {
   179			t.Error("breaker disabled by default, want armed")
   180		}
   181	
   182		off, err := NewRetry(func() RetryConfig {
   183			c := testRetryConfig(&fakeDLQ{})
   184			c.FloorAge = DisableFloorAge
   185			c.Backoff.NakDelay = 12 * time.Hour // legal only because nothing must fit the window
   186			return c
   187		}())
   188		if err != nil {
   189			t.Fatalf("NewRetry(DisableFloorAge): %v", err)
   190		}
   191		if off.breakerEnabled() {
   192			t.Error("breaker armed with DisableFloorAge")
   193		}
   194	}
