   196	// TestSettleRetriesOnTheLadder: the ordinary path — no floor observation yet,
   197	// deliveries left — naks with the ladder delay and touches nothing else.
   198	func TestSettleRetriesOnTheLadder(t *testing.T) {
   199		r, pub := newTestRetry(t, nil)
   200		msg := deliveredMsg(2774437, 2)
   201	
   202		s, err := r.Settle(t.Context(), msg, "checkpoint metadata not ready")
   203		if err != nil {
   204			t.Fatalf("Settle: %v", err)
   205		}
   206		if s.Outcome != OutcomeRetried || s.Cause != "" {
   207			t.Errorf("Settlement = %+v, want retried with no cause", s)
   208		}
   209		if want := []time.Duration{5 * time.Minute}; len(msg.NakDelays) != 1 || msg.NakDelays[0] != want[0] {
   210			t.Errorf("NakDelays = %v, want %v", msg.NakDelays, want)
   211		}
   212		if msg.Acked || msg.Termed {
   213			t.Errorf("message acked=%v termed=%v on a retry, want neither", msg.Acked, msg.Termed)
   214		}
   215		if len(pub.captured()) != 0 {
   216			t.Error("captured to the DLQ on a retry")
   217		}
   218	}
