   220	// TestSettleBreakerDeadLettersTheFloorBlocker is the ENT-1535 remedy: the
   221	// blocker at floor+1, on a floor stationary past the threshold, is captured
   222	// and Acked at delivery 2 — nowhere near the delivery cap that would
   223	// otherwise take ~43 minutes to reach.
   224	func TestSettleBreakerDeadLettersTheFloorBlocker(t *testing.T) {
   225		var got Settlement
   226		r, pub := newTestRetry(t, func(c *RetryConfig) {
   227			c.OnSettle = func(_ context.Context, _ jetstream.Msg, s Settlement) { got = s }
   228		})
   229		armFloor(r, 2774436, 16*time.Minute)
   230		msg := deliveredMsg(2774437, 2)
   231	
   232		s, err := r.Settle(t.Context(), msg, "re-queuing: update")
   233		if err != nil {
   234			t.Fatalf("Settle: %v", err)
   235		}
   236		if s.Outcome != OutcomeDeadLettered || s.Cause != CauseFloorAge {
   237			t.Fatalf("Settlement = %+v, want dead_lettered/floor_age", s)
   238		}
   239		if !msg.Acked {
   240			t.Error("blocker not Acked; the ack floor stays pinned")
   241		}
   242		if msg.Termed {
   243			t.Error("blocker Termed; a Term does not settle the message (ENT-1492)")
   244		}
   245		if len(msg.NakDelays) != 0 || msg.Naks != 0 {
   246			t.Errorf("blocker also naked (%d delayed, %d plain), want none", len(msg.NakDelays), msg.Naks)
   247		}
   248		if s.Floor != 2774436 || s.FloorAge != 16*time.Minute {
   249			t.Errorf("Settlement floor state = %d/%s, want 2774436/16m0s", s.Floor, s.FloorAge)
   250		}
   251		if got != s {
   252			t.Errorf("OnSettle saw %+v, want %+v", got, s)
   253		}
   254	
   255		captured := pub.captured()
   256		if len(captured) != 1 {
   257			t.Fatalf("captured %d messages, want 1", len(captured))
   258		}
   259		c := captured[0]
   260		if c.Subject != "repo.refs.dlq" {
   260		if c.Subject != "repo.refs.dlq" {
   261			t.Errorf("DLQ subject = %q, want repo.refs.dlq", c.Subject)
   262		}
   263		if string(c.Data) != "ref-event" {
   264			t.Errorf("DLQ payload = %q, want the raw message", c.Data)
   265		}
   266		if c.Header.Get("X-Entire-Repo") != "01KWHDFJ0C575CRVF18DPVSQW0" {
   267			t.Error("DLQ copy lost the original headers")
   268		}
   269		if reason := c.Header.Get(natsmsg.DLQReasonHeader); !strings.HasPrefix(reason, string(CauseFloorAge)+": ") {
   270			t.Errorf("DLQ reason = %q, want it prefixed with the cause", reason)
   271		}
   272		if c.Header.Get(natsmsg.DLQStreamSeqHeader) != "2774437" {
   273			t.Errorf("DLQ stream seq = %q, want 2774437", c.Header.Get(natsmsg.DLQStreamSeqHeader))
   274		}
   275	}
