   277	// TestSettleBreakerHoldsOff covers every way the breaker must NOT fire. Each
   278	// case would take an event away from a ladder it can still recover on —
   279	// ENT-1535's forensics found recoveries as late as attempt 4.
   280	func TestSettleBreakerHoldsOff(t *testing.T) {
   281		tests := []struct {
   282			name     string
   283			floorSeq uint64
   284			age      time.Duration
   285			msgSeq   uint64
   286			attempt  int
   287		}{
   288			{"floor stationary but not yet past the threshold", 2774436, 14 * time.Minute, 2774437, 3},
   289			{"message is not the blocker, just queued behind it", 2774436, 30 * time.Minute, 2774999, 3},
   290			{"message is below the floor entirely", 2774436, 30 * time.Minute, 2774400, 3},
   291			{"blocker on its first delivery has had no retry yet", 2774436, 30 * time.Minute, 2774437, 1},
   292		}
   293		for _, tt := range tests {
   294			t.Run(tt.name, func(t *testing.T) {
   295				r, pub := newTestRetry(t, nil)
   296				armFloor(r, tt.floorSeq, tt.age)
   297				msg := deliveredMsg(tt.msgSeq, tt.attempt)
   298	
   299				s, err := r.Settle(t.Context(), msg, "transient")
   300				if err != nil {
   301					t.Fatalf("Settle: %v", err)
   302				}
   303				if s.Outcome != OutcomeRetried {
   304					t.Fatalf("Settlement = %+v, want retried", s)
   305				}
   306				if msg.Acked || msg.Termed {
   307					t.Errorf("message acked=%v termed=%v, want it left on the ladder", msg.Acked, msg.Termed)
   308				}
   309				if len(pub.captured()) != 0 {
   310					t.Error("dead-lettered a message the breaker must hold off on")
   311				}
   312			})
   313		}
   314	}
