   316	// TestSettleReportsAnUnidentifiableBlocker: the breaker identifies the
   317	// blocker as the sequence immediately above the floor, which assumes the
   318	// consumer's filter is dense enough for that message to exist. When it isn't
   319	// — a narrow filter over a sparse stream — the breaker cannot fire, and that
   320	// must not be silent: the log names the sequence it wanted against the one it
   321	// saw, which is how a staging exercise tells "wrong predicate" apart from
   322	// "the real blocker is on another replica".
   323	func TestSettleReportsAnUnidentifiableBlocker(t *testing.T) {
   324		logs := &logCapture{}
   325		r, _ := newTestRetry(t, func(c *RetryConfig) { c.Logger = slog.New(logs) })
   326		armFloor(r, 2774436, 20*time.Minute)
   327	
   328		for range 3 { // logged once per stationary period, not once per delivery
   329			if _, err := r.Settle(t.Context(), deliveredMsg(2774600, 3), "transient"); err != nil {
   330				t.Fatalf("Settle: %v", err)
   331			}
   332		}
   333		const want = "search-indexer-refs: ack floor stalled but no delivery at floor+1; breaker cannot identify the blocker"
   334		if n := logs.count(want); n != 1 {
   335			t.Fatalf("logged the unidentifiable-blocker warning %d times, want exactly 1; saw %v", n, logs.snapshot())
   336		}
   337	
   338		// A message already below the floor is not a candidate blocker and says
   339		// nothing about a gap.
   340		r.gapLogged = false
   341		if _, err := r.Settle(t.Context(), deliveredMsg(2774400, 3), "transient"); err != nil {
   342			t.Fatalf("Settle: %v", err)
   343		}
   344		if logs.count(want) != 1 {
   345			t.Error("a settled-past sequence was reported as a floor gap")
   346		}
   347	}
