   349	// logCapture is a thread-safe slog.Handler that counts messages, so a test
   350	// can assert a log line is emitted once per stationary period rather than
   351	// once per delivery.
   352	type logCapture struct {
   353		mu   sync.Mutex
   354		msgs []string
   355	}
   356	
   357	func (h *logCapture) Enabled(context.Context, slog.Level) bool { return true }
   358	
   359	func (h *logCapture) Handle(_ context.Context, r slog.Record) error {
   360		h.mu.Lock()
   361		h.msgs = append(h.msgs, r.Message)
   362		h.mu.Unlock()
   363		return nil
   364	}
   365	
   366	func (h *logCapture) WithAttrs([]slog.Attr) slog.Handler { return h }
   367	func (h *logCapture) WithGroup(string) slog.Handler      { return h }
   368	
   369	func (h *logCapture) snapshot() []string {
   370		h.mu.Lock()
   371		defer h.mu.Unlock()
   372		return slices.Clone(h.msgs)
   373	}
   374	
   375	func (h *logCapture) count(msg string) int {
   376		n := 0
   377		for _, m := range h.snapshot() {
   378			if m == msg {
   379				n++
   380			}
   381		}
   382		return n
   383	}
