   385	// TestSettleBreakerNeedsAFloorObservation: with no reading yet — a process
   386	// that just started, or a poll that cannot reach the server — the breaker
   387	// stays out of the way. It may be late; it may never be early.
   388	func TestSettleBreakerNeedsAFloorObservation(t *testing.T) {
   389		r, pub := newTestRetry(t, nil)
   390		if _, _, ok := r.FloorStationaryFor(); ok {
   391			t.Fatal("FloorStationaryFor reports an observation before any poll")
   392		}
   393		msg := deliveredMsg(2774437, 4)
   394		if _, err := r.Settle(t.Context(), msg, "transient"); err != nil {
   395			t.Fatalf("Settle: %v", err)
   396		}
   397		if len(pub.captured()) != 0 || msg.Acked {
   398			t.Error("breaker fired with no ack-floor observation")
   399		}
