   402	// TestObserveFloorRestartsTheClockWhenTheFloorMoves: the trigger is
   403	// floor-stationary age, so an advancing floor — however slowly — is not a
   404	// stall, and re-observing the same floor must not restart the clock either.
   405	func TestObserveFloorRestartsTheClockWhenTheFloorMoves(t *testing.T) {
   406		r, _ := newTestRetry(t, nil)
   407		base := time.Now()
   408		now := base
   409		r.clock = func() time.Time { return now }
   410	
   411		r.observeFloor(100, base)
   412		now = base.Add(10 * time.Minute)
   413		r.observeFloor(100, now) // same floor: the clock keeps running
   414		if _, age, _ := r.FloorStationaryFor(); age != 10*time.Minute {
   415			t.Fatalf("age after re-observing the same floor = %s, want 10m0s", age)
   416		}
   417	
   418		r.observeFloor(101, now) // floor advanced: clock restarts
   419		floor, age, ok := r.FloorStationaryFor()
   420		if !ok || floor != 101 || age != 0 {
   421			t.Fatalf("after the floor moved: floor=%d age=%s ok=%v, want 101/0s/true", floor, age, ok)
   422		}
   423	
   424		// And the breaker is disarmed again for the new floor.
   425		msg := deliveredMsg(102, 4)
   426		if _, err := r.Settle(t.Context(), msg, "transient"); err != nil {
   427			t.Fatalf("Settle: %v", err)
   428		}
   429		if msg.Acked {
   430			t.Error("breaker fired against a floor that had just moved")
   431		}
   432	}
