330	// TestSettleBreakerHoldsOff covers every way the breaker must NOT fire. Each
331	// case would take an event away from a ladder it can still recover on —
332	// ENT-1535's forensics found recoveries as late as attempt 4.
333	func TestSettleBreakerHoldsOff(t *testing.T) {
334		tests := []struct {
335			name     string
336			floorSeq uint64
337			age      time.Duration
338			msgSeq   uint64
339			attempt  int
340		}{
341			{"floor stationary but not yet past the threshold", 2774436, 14 * time.Minute, 2774437, 3},
342			{"message is not the blocker, just queued behind it", 2774436, 30 * time.Minute, 2774999, 3},
343			{"message is below the floor entirely", 2774436, 30 * time.Minute, 2774400, 3},
344			{"blocker on its first delivery has had no retry yet", 2774436, 30 * time.Minute, 2774437, 1},
345		}
346		for _, tt := range tests {
347			t.Run(tt.name, func(t *testing.T) {
348				r, pub := newTestRetry(t, nil)
349				armFloor(r, tt.floorSeq, tt.age)
350				msg := deliveredMsg(tt.msgSeq, tt.attempt)
351	
352				s, err := r.Settle(t.Context(), msg, "transient")
353				if err != nil {
354					t.Fatalf("Settle: %v", err)
355				}
356				if s.Outcome != OutcomeRetried {
357					t.Fatalf("Settlement = %+v, want retried", s)
358				}
359				if msg.Acked || msg.Termed {
360					t.Errorf("message acked=%v termed=%v, want it left on the ladder", msg.Acked, msg.Termed)
361				}
362				if len(pub.captured()) != 0 {
363					t.Error("dead-lettered a message the breaker must hold off on")
364				}
365			})
366		}
