209	// TestRetryWithoutMonitorIsMessageLocal: omitting the monitor leaves Settle
210	// deciding from delivery metadata alone — no consumer-global inference, and
211	// no ack-floor poll. This is the composition an adopter uses when it wants to
212	// own the quarantine judgement itself.
213	func TestNewRetryDefaults(t *testing.T) {
214		r, _ := newTestRetry(t, nil)
215		if r.cfg.MinDeliveries != DefaultMinDeliveries {
216			t.Errorf("MinDeliveries = %d, want %d", r.cfg.MinDeliveries, DefaultMinDeliveries)
217		}
218		if r.cfg.CaptureReserve != DefaultCaptureReserve {
219			t.Errorf("CaptureReserve = %d, want %d", r.cfg.CaptureReserve, DefaultCaptureReserve)
220		}
221		if r.Monitor() == nil {
222			t.Error("Monitor() nil, want the configured monitor")
223		}
224	
225		// No monitor: a rung longer than any threshold is legal, because nothing
226		// has to fit inside a breaker window.
227		off, err := NewRetry(func() RetryConfig {
228			c := testRetryConfig(&fakeDLQ{})
229			c.Monitor = nil
230			c.Backoff.NakDelay = 12 * time.Hour
231			return c
232		}())
233		if err != nil {
234			t.Fatalf("NewRetry(no monitor): %v", err)
235		}
236		if off.Monitor() != nil {
237			t.Error("Monitor() non-nil without one configured")
238		}
239		msg := deliveredMsg(101, 2)
240		armStall(r.cfg.Monitor, 100, time.Hour) // a stall on someone else's monitor
240		armStall(r.cfg.Monitor, 100, time.Hour) // a stall on someone else's monitor
241		if _, err := off.Settle(t.Context(), msg, "transient"); err != nil {
242			t.Fatalf("Settle: %v", err)
243		}
244		if msg.Acked {
245			t.Error("a monitor-less Retry acted on consumer-global state")
246		}
247	}
