249	// TestSettleRetriesOnTheLadder: the ordinary path — no floor observation yet,
250	// deliveries left — naks with the ladder delay and touches nothing else.
251	func TestSettleRetriesOnTheLadder(t *testing.T) {
252		r, pub := newTestRetry(t, nil)
253		msg := deliveredMsg(2774437, 2)
