438	// TestSettleBreakerNeedsAFloorObservation: with no reading yet — a process
439	// that just started, or a poll that cannot reach the server — the breaker
440	// stays out of the way. It may be late; it may never be early.
441	func TestSettleBreakerNeedsAFloorObservation(t *testing.T) {
442		r, pub := newTestRetry(t, nil)
443		if _, _, ok := r.cfg.Monitor.FloorStall(); ok {
444			t.Fatal("FloorStall reports an observation before any poll")
445		}
446		msg := deliveredMsg(2774437, 2) // ladder deliveries left, so only the breaker could act
447		if _, err := r.Settle(t.Context(), msg, "transient"); err != nil {
448			t.Fatalf("Settle: %v", err)
449		}
450		if len(pub.captured()) != 0 || msg.Acked {
451			t.Error("breaker fired with no ack-floor observation")
452		}
453	}
