   818	// adopter that wants the stall signal but keeps the judgement itself: a
   819	// monitor on the Config, a Retry with no monitor, and the quarantine rule
   820	// written in the handler against FloorStall + DeadLetter. The library
   821	// supplies the observation and the non-lossy capture; the policy is the
   822	// adopter's.
   823	func TestFloorMonitorDrivesAnAdopterOwnedQuarantine(t *testing.T) {
   824		mon := mustFloorMonitor(FloorMonitorConfig{FloorAge: 10 * time.Minute})
   825		r, pub := newTestRetry(t, func(c *RetryConfig) { c.Monitor = nil })
   826	
   827		// The adopter's own rule, whatever shape it likes.
   828		quarantine := func(msg *natsmsgtest.FakeMsg) {
   829			if !mon.Stalled() {
   830				if _, err := r.Settle(t.Context(), msg, "transient"); err != nil {
   831					t.Fatalf("Settle: %v", err)
   832				}
   833				return
   834			}
   835			if _, err := r.DeadLetter(t.Context(), msg, "blocking a stalled floor"); err != nil {
   836				t.Fatalf("DeadLetter: %v", err)
   837			}
   838		}
   839	
   840		armStall(mon, 100, 5*time.Minute) // under the threshold
   841		healthy := deliveredMsg(101, 2)
   842		quarantine(healthy)
   843		if healthy.Acked || len(pub.captured()) != 0 {
   844			t.Fatal("quarantined a message while the monitor read healthy")
   845		}
   846	
   847		armStall(mon, 100, 30*time.Minute)
   848		blocker := deliveredMsg(101, 2)
   849		quarantine(blocker)
   850		if !blocker.Acked || len(pub.captured()) != 1 {
   851			t.Error("adopter-owned quarantine did not capture and settle the blocker")
   852		}
   853	}
