  1045	// poll so the connection it reads through is safe to drain afterwards.
  1046	func TestStartObservesTheAckFloor(t *testing.T) {
  1047		nc, js := runTestEnv(t)
  1048		if _, err := js.CreateStream(t.Context(), jetstream.StreamConfig{
  1049			Name: "repo_refs_v1", Subjects: []string{"repo.refs.>"},
  1050		}); err != nil {
  1051			t.Fatalf("create stream: %v", err)
  1052		}
