  1054			if _, err := js.Publish(t.Context(), "repo.refs.update", []byte("ref")); err != nil {
  1055				t.Fatalf("publish: %v", err)
  1056			}
  1057		}
  1058	
  1059		r, _ := newTestRetry(t, func(c *RetryConfig) {
  1060			c.Monitor = mustFloorMonitor(FloorMonitorConfig{
  1061				FloorAge: time.Minute, Poll: 10 * time.Millisecond, Name: "search-indexer-refs",
  1062			})
  1063			c.Backoff.NakDelay = time.Second
  1064		})
  1065		acked := make(chan struct{}, 3)
  1066		run, err := Start(t.Context(), nc, Config{
  1067			Stream:     "repo_refs_v1",
  1068			Durable:    "search_indexer_refs",
  1069			Name:       "search-indexer-refs",
  1070			MaxDeliver: 5,
  1071			Retry:      r,
  1072		}, func(m jetstream.Msg) {
  1073			if err := m.Ack(); err != nil {
  1074				t.Errorf("ack: %v", err)
  1075			}
  1076			acked <- struct{}{}
  1077		})
  1078		if err != nil {
  1079			t.Fatalf("Start: %v", err)
  1080		}
