  1082			select {
  1083			case <-acked:
  1084			case <-time.After(5 * time.Second):
  1085				t.Fatal("messages did not reach the handler")
  1086			}
  1087		}
  1088	
  1089		// The poll reads the durable's real ack floor. All three messages acked,
  1090		// so the consumer is caught up: the floor is at 3 and — correctly — NOT
  1091		// reported as stalled, because a floor that stops moving on a drained
  1092		// consumer is idleness, not a stall.
  1093		deadline := time.Now().Add(5 * time.Second)
