531	// Process runs the per-message prologue shared by every consumer: open the
532	// consumer span (re-parented to the producer across the NATS hop), decode the
533	// payload, and on a decode error record it, log "<Name>: decode <Stream>;
534	// term", invoke onUndecodable (so the caller bumps its own drop metric with
535	// its own attributes), and Term the message — a poison payload won't decode on
536	// redelivery. On success it invokes handle with the span-enriched context, the
537	// live span (for RecordError/SetStatus on the business error paths), the
538	// message, and the decoded event; with Config.KeepInProgress set, an AckWait
539	// heartbeat runs for the duration of handle.
540	//
541	// Callers wire Process as the func they pass to Start AND the entry point
542	// their tests drive, so the decode-or-term path is exercised the same way in
543	// production and tests.
544	func Process[E any](
545		ctx context.Context,
546		msg jetstream.Msg,
547		cfg Config,
548		decode func([]byte) (E, error),
549		handle func(ctx context.Context, span trace.Span, msg jetstream.Msg, ev E),
550		onUndecodable func(ctx context.Context),
551	) {
552		ctx, span := natsmsg.StartConsumerSpan(ctx, cfg.tracer(), msg, cfg.SpanName)
553		defer span.End()
554	
555		ev, err := decode(msg.Data())
556		if err != nil {
557			span.RecordError(err)
558			span.SetStatus(codes.Error, "decode")
559			disposition := "term"
560			if cfg.Retry != nil {
561				disposition = "dead-letter"
562			}
563			cfg.logger().WarnContext(ctx, cfg.Name+": decode "+cfg.Stream+"; "+disposition,
564				slog.Any("error", err), slog.String("subject", msg.Subject()))
565			if onUndecodable != nil {
566				onUndecodable(ctx)
567			}
568			if cfg.Retry != nil {
569				// Same terminal effect as the Term below, but the payload
570				// survives: a bare Term is the last drop-without-a-record surface
571				// in this scaffold, and a Retry is exactly the capture path that
572				// closes it.
573				if _, dlErr := cfg.Retry.DeadLetter(ctx, msg, "undecodable: "+err.Error()); dlErr != nil {
574					cfg.logger().WarnContext(ctx, cfg.Name+": dead-letter undecodable failed", slog.Any("error", dlErr))
575				}
576				return
577			}
578			if termErr := msg.Term(); termErr != nil {
579				cfg.logger().WarnContext(ctx, cfg.Name+": term failed", slog.Any("error", termErr))
580			}
581			return
582		}
583		if cfg.KeepInProgress {
584			stop := natsmsg.KeepInProgress(msg.InProgress, cfg.EffectiveAckWait())
585			defer stop()
586		}
587		handle(ctx, span, msg, ev)
588	}

