func TestAdversarialFilteredBlockerUsesConsumerSequence(t *testing.T) {
	r, pub := newTestRetry(t, nil)
	armStall(r.Monitor(), 100, DefaultFloorAge+time.Minute)

	// Consumer sequence 2 is immediately above consumer ack-floor 1, even
	// though filtering mapped it to sparse stream sequence 200.
	msg := deliveredMsg(200, DefaultMinDeliveries)
	msg.Meta.Sequence.Consumer = 2
	s, err := r.Settle(t.Context(), msg, "transient")
	if err != nil {
		t.Fatalf("Settle: %v", err)
	}
	if s.Outcome != OutcomeDeadLettered {
		t.Fatalf("filtered floor blocker was not broken: settlement=%+v captured=%d", s, len(pub.captured()))
	}
}

type ackFailMsg struct{ jetstream.Msg }

func (ackFailMsg) Ack() error { return errors.New("connection closed") }

func TestAdversarialFinalAckFailureIsNotARetry(t *testing.T) {
	nc, js := runTestEnv(t)
	if _, err := js.CreateStream(t.Context(), jetstream.StreamConfig{
		Name: "review_wq", Subjects: []string{"review.wq"}, Retention: jetstream.WorkQueuePolicy,
	}); err != nil {
		t.Fatal(err)
	}
	pub := &fakeDLQ{}
	r, err := NewRetry(RetryConfig{
		Backoff: backoff.Policy{NakDelay: 10 * time.Millisecond, MaxDeliver: 2},
		CaptureReserve: NoCaptureReserve, DLQSubject: "review.dlq", Publisher: pub,
	})
	if err != nil {
		t.Fatal(err)
	}
	type result struct {
		s Settlement
		e error
	}
	results := make(chan result, 3)
	run, err := Start(t.Context(), nc, Config{
		Stream: "review_wq", Durable: "review", Name: "review",
		AckWait: 20 * time.Millisecond, MaxDeliver: 2, Retry: r,
	}, func(msg jetstream.Msg) {
		s, e := r.Settle(t.Context(), ackFailMsg{Msg: msg}, "transient")
		results <- result{s, e}
	})
	if err != nil {
		t.Fatal(err)
	}
	defer run.Stop()
	if _, err := js.Publish(t.Context(), "review.wq", []byte("work")); err != nil {
		t.Fatal(err)
	}
	for want := 1; want <= 2; want++ {
		select {
		case got := <-results:
			t.Logf("delivery %d: settlement=%+v err=%v", want, got.s, got.e)
		case <-time.After(time.Second):
			t.Fatalf("delivery %d did not arrive", want)
		}
	}
	select {
	case got := <-results:
		t.Logf("unexpected third delivery: settlement=%+v err=%v", got.s, got.e)
	case <-time.After(250 * time.Millisecond):
		t.Fatal("final Ack failure reported OutcomeRetried, but MaxDeliver allowed no next delivery")
	}
}

