456	// Run supervises the consume loop [Start] builds. Where Start is one-shot —
457	// an error at consumer creation is returned, and a consume loop that closes
458	// underneath the caller (consumer deleted on the server, subscription
459	// invalidated) stays closed — Run retries both with exponential backoff
460	// (runRetryInitial doubling to runRetryMax, reset after a loop that outlives
461	// the max). In particular a stream that is not provisioned yet at boot — the
462	// declarative-provisioning race — is a retry, not a crash.
463	//
464	// Run blocks until ctx is cancelled, then joins the live loop (including an
465	// in-flight handler, see [Runner.Stop]) before returning, so it composes with
466	// the cancel → join → drain shutdown ordering as the body of a supervised
467	// goroutine:
468	//
469	//	g.Go(func(ctx context.Context) {
470	//		if err := jsconsumer.Run(ctx, nc, cfg, onMsg); err != nil {
471	//			log.Error("consumer config rejected", "error", err)
472	//		}
473	//	})
474	//
475	// Local configuration errors and permanent server responses (invalid consumer
476	// configuration, authorization/account setup) can never succeed on retry and
477	// are returned immediately. A missing declarative stream, temporary transport
478	// failure, or unknown server-side 5xx response remains supervised. A nil return
479	// means a clean, ctx-driven exit.
480	func Run(ctx context.Context, nc *nats.Conn, cfg Config, onMsg func(jetstream.Msg)) error {
481		if err := cfg.validate(nc, onMsg); err != nil {
482			return err
483		}
484		delay := runRetryInitial
485		for {
486			// Each attempt gets a child context so the cancel-watcher goroutine
487			// Start arms is released when the attempt dies, instead of one
488			// accumulating per recreate for the life of the process.
489			attemptCtx, cancelAttempt := context.WithCancel(ctx)
490			r, err := Start(attemptCtx, nc, cfg, onMsg)
491			if err != nil {
492				cancelAttempt()
493				if ctx.Err() != nil {
494					return nil //nolint:nilerr // a Start error during shutdown is a clean, ctx-driven exit, not a fault to report
495				}
496				if !isRetryableStartError(err) {
497					return err
498				}
499				cfg.logger().WarnContext(ctx, cfg.Name+": start consumer failed; retrying",
500					slog.Any("error", err), slog.Duration("retry_in", delay))
501			} else {
502				started := time.Now()
503				select {
504				case <-ctx.Done():
505					r.Stop()
506					cancelAttempt()
507					return nil
508				case <-r.closed:
509					cancelAttempt()
510					if ctx.Err() != nil {
511						return nil //nolint:nilerr // the loop closing during shutdown is the expected wind-down, not a fault
512					}
513					// A loop that ran long enough to be called healthy earns a
514					// fresh envelope; a flapping one keeps escalating.
515					if time.Since(started) >= runRetryMax {
516						delay = runRetryInitial
517					}
518					cfg.logger().WarnContext(ctx, cfg.Name+": consume loop closed; recreating",
519						slog.Duration("retry_in", delay))
520				}
521			}
522			select {
523			case <-ctx.Done():
524				return nil
525			case <-time.After(delay):
526			}
527			delay = min(delay*2, runRetryMax)
528		}
529	}
530	
531	// Process runs the per-message prologue shared by every consumer: open the
532	// consumer span (re-parented to the producer across the NATS hop), decode the
533	// payload, and on a decode error record it, log "<Name>: decode <Stream>;
534	// term", invoke onUndecodable (so the caller bumps its own drop metric with
535	// its own attributes), and Term the message — a poison payload won't decode on

