 462	// TestObserveFloorRestartsTheClockWhenTheFloorMoves: an advancing floor —
 463	// however slowly — is not a stall, and re-observing the same stalled floor
 464	// must not restart the clock either.
 465	func TestObserveFloorRestartsTheClockWhenTheFloorMoves(t *testing.T) {
 466		r, _ := newTestRetry(t, nil)
 467		base := time.Now()
 468		now := base
 469		r.cfg.Monitor.clock = func() time.Time { return now }
 470	
 471		r.cfg.Monitor.observeFloor(100, 200, base)
 472		now = base.Add(10 * time.Minute)
 473		r.cfg.Monitor.observeFloor(100, 200, now) // same stall: the clock keeps running
 474		if _, age, _ := r.cfg.Monitor.FloorStall(); age != 10*time.Minute {
 475			t.Fatalf("age after re-observing the same floor = %s, want 10m0s", age)
 476		}
 477	
 478		r.cfg.Monitor.observeFloor(101, 200, now) // floor advanced: clock restarts
 479		floor, age, ok := r.cfg.Monitor.FloorStall()
 480		if !ok || floor != 101 || age != 0 {
 481			t.Fatalf("after the floor moved: floor=%d age=%s ok=%v, want 101/0s/true", floor, age, ok)
 482		}
 483	
 484		// And the breaker is disarmed again for the new floor.
 485		msg := deliveredMsg(102, 2)
 486		if _, err := r.Settle(t.Context(), msg, "transient"); err != nil {
 487			t.Fatalf("Settle: %v", err)
 488		}
 489		if msg.Acked {
 490			t.Error("breaker fired against a floor that had just moved")
 491		}
 492	}
