 494	// TestObserveFloorIgnoresACaughtUpConsumer is the false positive that makes
 495	// the difference between a poison remedy and a message shredder: a quiet
 496	// consumer's floor sits still because NOTHING ARRIVED, not because anything
 497	// is stuck. Crediting the next message to arrive with that idle time would
 498	// dead-letter it on its second delivery. The stall clock therefore runs only
 499	// while the consumer has delivered past its own floor, and starts when the
 500	// gap opens — not when the floor last moved.
 501	func TestObserveFloorIgnoresACaughtUpConsumer(t *testing.T) {
 502		r, pub := newTestRetry(t, nil)
 503		base := time.Now()
 504		now := base
 505		r.cfg.Monitor.clock = func() time.Time { return now }
 506	
 507		// Four idle hours, fully caught up: floor stationary, but not stalled.
 508		r.cfg.Monitor.observeFloor(100, 100, base)
 509		now = base.Add(4 * time.Hour)
 510		r.cfg.Monitor.observeFloor(100, 100, now)
 511		if _, age, stalled := r.cfg.Monitor.FloorStall(); stalled {
 512			t.Fatalf("a caught-up consumer reported as stalled for %s", age)
 513		}
 514	
 515		// A message finally arrives and fails its way to breaker eligibility. The
 516		// breaker must still not fire: the stall clock starts now, not four hours ago.
 517		r.cfg.Monitor.observeFloor(100, 101, now)
 518		msg := deliveredMsg(101, breakerDelivery)
 519		if _, err := r.Settle(t.Context(), msg, "transient"); err != nil {
 520			t.Fatalf("Settle: %v", err)
 521		}
 522		if msg.Acked || len(pub.captured()) != 0 {
 523			t.Fatal("breaker dead-lettered a message credited with the consumer's idle time")
 524		}
 525	
 526		// Once the gap has genuinely persisted past the threshold, it fires.
 527		now = now.Add(16 * time.Minute)
 528		blocker := deliveredMsg(101, breakerDelivery)
 529		if _, err := r.Settle(t.Context(), blocker, "re-queuing: update"); err != nil {
 530			t.Fatalf("Settle: %v", err)
 531		}
 532		if !blocker.Acked || len(pub.captured()) != 1 {
 533			t.Error("breaker did not fire on a stall that really had persisted")
 534		}
 535	}
