1094	// the breaker's input is the durable's real ack floor, and Stop joins the
1095	// poll so the connection it reads through is safe to drain afterwards.
1096	func TestStartObservesTheAckFloor(t *testing.T) {
1097		nc, js := runTestEnv(t)
1098		if _, err := js.CreateStream(t.Context(), jetstream.StreamConfig{
1099			Name: "repo_refs_v1", Subjects: []string{"repo.refs.>"},
1100		}); err != nil {
1101			t.Fatalf("create stream: %v", err)
1102		}
1103		for range 3 {
1104			if _, err := js.Publish(t.Context(), "repo.refs.update", []byte("ref")); err != nil {
1105				t.Fatalf("publish: %v", err)
1106			}
1107		}
1108	
1109		r, _ := newTestRetry(t, func(c *RetryConfig) {
1110			c.Monitor = mustFloorMonitor(FloorMonitorConfig{
1111				FloorAge: time.Minute, Poll: 10 * time.Millisecond, Name: "search-indexer-refs",
1112			})
1113			c.Backoff.NakDelay = time.Second
1114		})
1115		acked := make(chan struct{}, 3)
1116		run, err := Start(t.Context(), nc, Config{
1117			Stream:     "repo_refs_v1",
1118			Durable:    "search_indexer_refs",
1119			Name:       "search-indexer-refs",
1120			MaxDeliver: 6,
1121			Retry:      r,
1122		}, func(m jetstream.Msg) {
1123			if err := m.Ack(); err != nil {
1124				t.Errorf("ack: %v", err)
1125			}
1126			acked <- struct{}{}
1127		})
1128		if err != nil {
1129			t.Fatalf("Start: %v", err)
1130		}
1131		for range 3 {
1132			select {
1133			case <-acked:
1134			case <-time.After(5 * time.Second):
1135				t.Fatal("messages did not reach the handler")
1136			}
