1171	// TestRunJoinsThePollBeforeRecreating: Run recreates a consume loop that
1172	// closed underneath it, and reattaches the SAME monitor to the new consumer.
1173	// If it only cancelled the attempt instead of joining, the old poll could
1174	// still be in an in-flight consumer-info request whose reply lands after the
1175	// reattach and overwrites fresh state with stale — or races the attach
1176	// outright. Driven with a fast poll under -race, and asserted on the state
1177	// the monitor is left in.
1178	func TestRunJoinsThePollBeforeRecreating(t *testing.T) {
1179		compressRunRetries(t)
1180		nc, js := runTestEnv(t)
1181		if _, err := js.CreateStream(t.Context(), jetstream.StreamConfig{
1182			Name: "repo_refs_v1", Subjects: []string{"repo.refs.>"},
1183		}); err != nil {
1184			t.Fatalf("create stream: %v", err)
1185		}
1186		mon := mustFloorMonitor(FloorMonitorConfig{
1187			FloorAge: time.Minute, Poll: time.Millisecond, Name: "recreate",
1188		})
1189		r, _ := newTestRetry(t, func(c *RetryConfig) {
1190			c.Monitor = mon
1191			c.Backoff.NakDelay = time.Second
1192		})
1193	
1194		ctx, cancel := context.WithCancel(t.Context())
1195		defer cancel()
1196		done := make(chan error, 1)
1197		go func() {
1198			done <- Run(ctx, nc, Config{
1199				Stream: "repo_refs_v1", Durable: "recreate_durable",
1200				Name: "recreate", MaxDeliver: 6, Retry: r,
1201			}, func(m jetstream.Msg) {
1202				if err := m.Ack(); err != nil {
1203					t.Errorf("ack: %v", err)
1204				}
1205			})
1206		}()
1207	
1208		// Force several close-and-recreate cycles by deleting the durable out
1209		// from under the live consume loop.
1210		for range 3 {
1211			deadline := time.Now().Add(5 * time.Second)
1212			for {
1213				if _, err := js.Consumer(t.Context(), "repo_refs_v1", "recreate_durable"); err == nil {
1214					break
1215				}
1216				if time.Now().After(deadline) {
1217					t.Fatal("consumer never appeared")
1218				}
1219				time.Sleep(5 * time.Millisecond)
1220			}
1221			if err := js.DeleteConsumer(t.Context(), "repo_refs_v1", "recreate_durable"); err != nil {
1222				t.Fatalf("delete consumer: %v", err)
1223			}
1224			time.Sleep(60 * time.Millisecond)
1225		}
1226	
1227		cancel()
1228		select {
1229		case err := <-done:
1230			if err != nil {
1231				t.Fatalf("Run: %v", err)
1232			}
1233		case <-time.After(10 * time.Second):
1234			t.Fatal("Run did not return after ctx cancel")
1235		}
1236		// The monitor belongs to one consumer, so at no point may two polls have
1237		// been live: a second one means Run reattached while the previous poll was
1238		// still running, and that poll's in-flight reply describes a consumer that
1239		// no longer exists.
1240		mon.mu.Lock()
1241		maxPolls, live := mon.maxPolls, mon.polls
1242		mon.mu.Unlock()
1243		if maxPolls > 1 {
1244			t.Errorf("%d ack-floor polls were live at once; Run reattached the monitor without joining the old one", maxPolls)
1245		}
1246		if live != 0 {
1247			t.Errorf("%d ack-floor polls still live after Run returned", live)
1248		}
1249		// A drained consumer is not stalled; a stale reading from a dead consumer
1250		// is exactly what would leave a phantom stall behind.
1251		if _, age, stalled := mon.FloorStall(); stalled {
1252			t.Errorf("monitor left reporting a stall (%s) after recreates on an empty stream", age)
1253		}
1254	}
