 403	// TestSettleBreakerHoldsOff covers every way the quarantine conjunction must
 404	// fail closed. Each case would take an event away from a ladder it can still
 405	// recover on — ENT-1535's forensics found recoveries as late as attempt 4.
 406	func TestSettleBreakerHoldsOff(t *testing.T) {
 407		tests := []struct {
 408			name     string
 409			floorSeq uint64
 410			age      time.Duration
 411			msgSeq   uint64
 412			attempt  int
 413		}{
 414			{"floor stalled but not yet past the threshold", 2774436, 14 * time.Minute, 2774437, breakerDelivery},
 415			{"message already settled below the floor", 2774436, 30 * time.Minute, 2774400, breakerDelivery},
 416			{"message has not itself been failing long enough", 2774436, 30 * time.Minute, 2774437, breakerDelivery - 1},
 417			{"message on its first delivery has had no retry at all", 2774436, 30 * time.Minute, 2774437, 1},
 418		}
 419		for _, tt := range tests {
 420			t.Run(tt.name, func(t *testing.T) {
 421				r, pub := newTestRetry(t, nil)
 422				armFloor(r, tt.floorSeq, tt.age)
 423				msg := deliveredMsg(tt.msgSeq, tt.attempt)
 424	
 425				s, err := r.Settle(t.Context(), msg, "transient")
 426				if err != nil {
 427					t.Fatalf("Settle: %v", err)
 428				}
 429				if s.Outcome != OutcomeRetried {
 430					t.Fatalf("Settlement = %+v, want retried", s)
 431				}
 432				if s.BreakerTripped {
 433					t.Error("Settlement reports a trip the conjunction should have refused")
 434				}
 435				if msg.Acked || msg.Termed {
