1093	// TestStartObservesTheAckFloor drives the poll loop against a live consumer:
1094	// the breaker's input is the durable's real ack floor, and Stop joins the
1095	// poll so the connection it reads through is safe to drain afterwards.
1096	func TestStartObservesTheAckFloor(t *testing.T) {
1097		nc, js := runTestEnv(t)
1098		if _, err := js.CreateStream(t.Context(), jetstream.StreamConfig{
1099			Name: "repo_refs_v1", Subjects: []string{"repo.refs.>"},
1100		}); err != nil {
1101			t.Fatalf("create stream: %v", err)
1102		}
1103		for range 3 {
1104			if _, err := js.Publish(t.Context(), "repo.refs.update", []byte("ref")); err != nil {
1105				t.Fatalf("publish: %v", err)
1106			}
1107		}
1108	
1109		r, _ := newTestRetry(t, func(c *RetryConfig) {
1110			c.Monitor = mustFloorMonitor(FloorMonitorConfig{
1111				FloorAge: time.Minute, Poll: 10 * time.Millisecond, Name: "search-indexer-refs",
1112			})
1113			c.Backoff.NakDelay = time.Second
1114		})
1115		acked := make(chan struct{}, 3)
1116		run, err := Start(t.Context(), nc, Config{
1117			Stream:     "repo_refs_v1",
1118			Durable:    "search_indexer_refs",
1119			Name:       "search-indexer-refs",
1120			MaxDeliver: 6,
1121			Retry:      r,
1122		}, func(m jetstream.Msg) {
1123			if err := m.Ack(); err != nil {
1124				t.Errorf("ack: %v", err)
1125			}
1126			acked <- struct{}{}
1127		})
1128		if err != nil {
1129			t.Fatalf("Start: %v", err)
1130		}
1131		for range 3 {
1132			select {
1133			case <-acked:
1134			case <-time.After(5 * time.Second):
1135				t.Fatal("messages did not reach the handler")
1136			}
1137		}
1138	
1139		// The poll reads the durable's real ack floor. All three messages acked,
1140		// so the consumer is caught up: the floor is at 3 and — correctly — NOT
1141		// reported as stalled, because a floor that stops moving on a drained
1142		// consumer is idleness, not a stall.
1143		deadline := time.Now().Add(5 * time.Second)
1144		for {
1145			floor, _, stalled := r.cfg.Monitor.FloorStall()
1146			if floor == 3 {
1147				if stalled {
1148					t.Fatal("a fully drained consumer reported as stalled")
1149				}
1150				break
1151			}
1152			if time.Now().After(deadline) {
1153				t.Fatalf("ack floor never observed at 3 (got %d)", floor)
1154			}
1155			time.Sleep(5 * time.Millisecond)
1156		}
1157	
1158		// Stop joins the poll loop, so nothing is still reading through nc.
1159		done := make(chan struct{})
1160		go func() { run.Stop(); close(done) }()
1161		select {
1162		case <-done:
1163		case <-time.After(5 * time.Second):
1164			t.Fatal("Stop did not join the ack-floor poll")
1165		}
1166		if got := r.Monitor().pollInterval(); got != 10*time.Millisecond {
1167			t.Errorf("pollInterval = %s, want the configured 10ms", got)
1168		}
1169	}
