720	// the caller just has to hear about it (settle:dlq_ack_failed).
721	func TestSettleReportsAckFailureAfterCapture(t *testing.T) {
722		r, pub := newTestRetry(t, nil)
723		armFloor(r, 2774436, 20*time.Minute)
724		msg := deliveredMsg(2774437, breakerDelivery)
725		msg.AckErr = errors.New("connection closed")
726	
727		s, err := r.Settle(t.Context(), msg, "re-queuing: update")
728		if err == nil || !strings.Contains(err.Error(), "settle:dlq_ack_failed") {
729			t.Fatalf("Settle err = %v, want settle:dlq_ack_failed", err)
730		}
731		if len(pub.captured()) != 1 {
732			t.Errorf("captured %d messages, want the copy to have landed first", len(pub.captured()))
733		}
734		if s.Outcome != OutcomeRetried {
735			t.Errorf("Outcome = %q, want the message reported as still coming back, not dead-lettered", s.Outcome)
736		}
737		if msg.Termed {
738			t.Error("message Termed after a failed Ack")
739		}
740	}
741	
742	// TestSettleStrandsWhenTheFinalAckFails is the other half of the
743	// classification: the capture succeeded, so the data is safe, but the ack
744	// that would release the floor did not land and no further delivery is
745	// coming. Reporting that as "retried" tells the adopter's metrics the
746	// opposite of the truth — the broker permits no next delivery, so nothing
747	// retries. Captured is what separates it from a stranding that saved nothing.
748	func TestSettleStrandsWhenTheFinalAckFails(t *testing.T) {
749		r, pub := newTestRetry(t, nil)
750		msg := deliveredMsg(2774437, finalDelivery)
751		msg.AckErr = errors.New("connection closed")
752	
753		s, err := r.Settle(t.Context(), msg, "still not ready")
754		if err == nil || !strings.Contains(err.Error(), "settle:dlq_ack_failed") {
755			t.Fatalf("Settle err = %v, want settle:dlq_ack_failed", err)
756		}
757		if s.Outcome != OutcomeStranded {
758			t.Fatalf("Outcome = %q, want %q — no delivery remains, so nothing will retry", s.Outcome, OutcomeStranded)
759		}
760		if !s.Captured {
