260	// TestSettleRetriesOnTheLadder: the ordinary path — no floor observation yet,
261	// deliveries left — naks with the ladder delay and touches nothing else.
262	func TestSettleRetriesOnTheLadder(t *testing.T) {
263		r, pub := newTestRetry(t, nil)
264		msg := deliveredMsg(2774437, 2)
265	
266		s, err := r.Settle(t.Context(), msg, "checkpoint metadata not ready")
267		if err != nil {
268			t.Fatalf("Settle: %v", err)
269		}
270		if s.Outcome != OutcomeRetried || s.Cause != "" {
271			t.Errorf("Settlement = %+v, want retried with no cause", s)
272		}
273		if want := []time.Duration{5 * time.Minute}; len(msg.NakDelays) != 1 || msg.NakDelays[0] != want[0] {
274			t.Errorf("NakDelays = %v, want %v", msg.NakDelays, want)
275		}
276		if msg.Acked || msg.Termed {
277			t.Errorf("message acked=%v termed=%v on a retry, want neither", msg.Acked, msg.Termed)
278		}
279		if len(pub.captured()) != 0 {
280			t.Error("captured to the DLQ on a retry")
281		}
282	}
283	
284	// TestSettleBreakerDeadLettersThroughAStall is the ENT-1535 remedy, and the
285	// regression test for the filtered-consumer defect: the message sits at a
286	// stream sequence far above the ack floor, exactly as a poison event does when
287	// non-matching subjects sit between it and the floor. An identification rule
288	// keyed on floor+1 misses it (measured against a live server: floor 2, blocker
289	// at stream 6); the conjunction does not.
290	func TestSettleBreakerDeadLettersThroughAStall(t *testing.T) {
291		var got Settlement
292		r, pub := newTestRetry(t, func(c *RetryConfig) {
293			c.OnSettle = func(_ context.Context, _ jetstream.Msg, s Settlement) { got = s }
294		})
295		armFloor(r, 2774436, 16*time.Minute)
296		msg := deliveredMsg(2774600, breakerDelivery) // 164 sequences above the floor
297	
298		s, err := r.Settle(t.Context(), msg, "re-queuing: update")
299		if err != nil {
300			t.Fatalf("Settle: %v", err)
301		}
302		if s.Outcome != OutcomeDeadLettered || s.Cause != CauseFloorAge {
303			t.Fatalf("Settlement = %+v, want dead_lettered/floor_age", s)
304		}
305		if !s.BreakerTripped || !s.Captured {
306			t.Errorf("Settlement = %+v, want the trip and the capture both reported", s)
307		}
308		if s.FailingFor != 15*time.Minute {
309			t.Errorf("FailingFor = %s, want 15m0s (three 5-minute rungs served)", s.FailingFor)
310		}
311		if !msg.Acked {
312			t.Error("blocker not Acked; the ack floor stays pinned")
313		}
314		if msg.Termed {
315			t.Error("blocker Termed; a Term does not settle the message (ENT-1492)")
316		}
317		if len(msg.NakDelays) != 0 || msg.Naks != 0 {
318			t.Errorf("blocker also naked (%d delayed, %d plain), want none", len(msg.NakDelays), msg.Naks)
319		}
320		if s.Floor != 2774436 || s.FloorAge != 16*time.Minute {
321			t.Errorf("Settlement floor state = %d/%s, want 2774436/16m0s", s.Floor, s.FloorAge)
322		}
323		if got != s {
324			t.Errorf("OnSettle saw %+v, want %+v", got, s)
325		}
326	
327		captured := pub.captured()
328		if len(captured) != 1 {
329			t.Fatalf("captured %d messages, want 1", len(captured))
330		}
331		c := captured[0]
332		if c.Subject != "repo.refs.dlq" {
333			t.Errorf("DLQ subject = %q, want repo.refs.dlq", c.Subject)
334		}
335		if string(c.Data) != "ref-event" {
336			t.Errorf("DLQ payload = %q, want the raw message", c.Data)
337		}
338		if c.Header.Get("X-Entire-Repo") != "01KWHDFJ0C575CRVF18DPVSQW0" {
339			t.Error("DLQ copy lost the original headers")
340		}
341		if reason := c.Header.Get(natsmsg.DLQReasonHeader); !strings.HasPrefix(reason, string(CauseFloorAge)+": ") {
342			t.Errorf("DLQ reason = %q, want it prefixed with the cause", reason)
343		}
344		if c.Header.Get(natsmsg.DLQStreamSeqHeader) != "2774600" {
345			t.Errorf("DLQ stream seq = %q, want 2774600", c.Header.Get(natsmsg.DLQStreamSeqHeader))
346		}
347	}
348	
349	// TestBreakerIsIndependentOfTheGapToTheFloor pins the property directly: the
350	// distance between the message and the ack floor must not change the outcome,
351	// because that distance is a function of the consumer's filter and of whether
352	// the server last recomputed the floor from a pending scan or a drain.
353	func TestBreakerIsIndependentOfTheGapToTheFloor(t *testing.T) {
354		for _, seq := range []uint64{100 + 1, 100 + 2, 100 + 164, 100 + 100000} {
355			r, pub := newTestRetry(t, nil)
356			armFloor(r, 100, 20*time.Minute)
357			msg := deliveredMsg(seq, breakerDelivery)
358			if _, err := r.Settle(t.Context(), msg, "transient"); err != nil {
359				t.Fatalf("Settle(seq %d): %v", seq, err)
360			}
361			if !msg.Acked || len(pub.captured()) != 1 {
362				t.Errorf("seq %d (floor+%d) not dead-lettered; the breaker is gap-sensitive", seq, seq-100)
363			}
364		}
