   367	// logCapture is a thread-safe slog.Handler that counts messages, so a test
   368	// can assert a log line is emitted once per stationary period rather than
   369	// once per delivery.
   370	type logCapture struct {
   371		mu   sync.Mutex
   372		msgs []string
   373	}
   374	
   375	func (h *logCapture) Enabled(context.Context, slog.Level) bool { return true }
   376	
   377	func (h *logCapture) Handle(_ context.Context, r slog.Record) error {
   378		h.mu.Lock()
   379		h.msgs = append(h.msgs, r.Message)
   380		h.mu.Unlock()
   381		return nil
   382	}
   383	
   384	func (h *logCapture) WithAttrs([]slog.Attr) slog.Handler { return h }
   385	func (h *logCapture) WithGroup(string) slog.Handler      { return h }
   386	
   387	func (h *logCapture) snapshot() []string {
   388		h.mu.Lock()
   389		defer h.mu.Unlock()
   390		return slices.Clone(h.msgs)
   391	}
   392	
   393	func (h *logCapture) count(msg string) int {
   394		n := 0
   395		for _, m := range h.snapshot() {
   396			if m == msg {
   397				n++
   398			}
   399		}
   400		return n
   401	}
