package jsconsumer

import (
	"testing"
	"time"

	"github.com/nats-io/nats.go/jetstream"

	"github.com/entireio/go-nuts/backoff"
)

func TestAdversarialAckWaitDeliveriesDoNotProveLadderAge(t *testing.T) {
	nc, js := runTestEnv(t)
	if _, err := js.CreateStream(t.Context(), jetstream.StreamConfig{
		Name: "review_age", Subjects: []string{"review.age"}, Retention: jetstream.WorkQueuePolicy,
	}); err != nil {
		t.Fatal(err)
	}
	cons, err := js.CreateConsumer(t.Context(), "review_age", jetstream.ConsumerConfig{
		Durable: "review_age", AckPolicy: jetstream.AckExplicitPolicy,
		AckWait: 20 * time.Millisecond, MaxDeliver: 6,
	})
	if err != nil {
		t.Fatal(err)
	}
	mon := mustFloorMonitor(FloorMonitorConfig{FloorAge: 3 * time.Second})
	armStall(mon, 0, 4*time.Second) // an older, consumer-global stall
	pub := &fakeDLQ{}
	r, err := NewRetry(RetryConfig{
		Backoff: backoff.Policy{NakDelay: time.Second, MaxDeliver: 6},
		Monitor: mon, Breaker: BreakerEnforce,
		DLQSubject: "review.dlq", Publisher: pub,
	})
	if err != nil {
		t.Fatal(err)
	}
	done := make(chan Settlement, 1)
	started := time.Now()
	cc, err := cons.Consume(func(msg jetstream.Msg) {
		meta, metaErr := msg.Metadata()
		if metaErr != nil {
			t.Errorf("metadata: %v", metaErr)
			return
		}
		if meta.NumDelivered < 4 {
			return // simulate crash/return before Settle; AckWait redelivers
		}
		s, settleErr := r.Settle(t.Context(), msg, "transient")
		if settleErr != nil {
			t.Errorf("Settle: %v", settleErr)
		}
		done <- s
	}, jetstream.PullMaxMessages(1))
	if err != nil {
		t.Fatal(err)
	}
	defer cc.Stop()
	if _, err := js.Publish(t.Context(), "review.age", []byte("work")); err != nil {
		t.Fatal(err)
	}
	select {
	case s := <-done:
		elapsed := time.Since(started)
		if s.Outcome == OutcomeDeadLettered && elapsed < time.Second {
			t.Fatalf("message dead-lettered after %s actual time because delivery count inferred FailingFor=%s", elapsed, s.FailingFor)
		}
	case <-time.After(2 * time.Second):
		t.Fatal("fourth delivery did not arrive")
	}
}

