 430	// TestSettleBreakerHoldsOff covers every way the quarantine conjunction must
 431	// fail closed. Each case would take an event away from a ladder it can still
 432	// recover on — ENT-1535's forensics found recoveries as late as attempt 4.
 433	func TestSettleBreakerHoldsOff(t *testing.T) {
 434		tests := []struct {
 435			name       string
 436			floorSeq   uint64
 437			age        time.Duration
 438			msgSeq     uint64
 439			attempt    int
 440			failingFor time.Duration
 441		}{
 442			{"floor stalled but not yet past the threshold", 2774436, 14 * time.Minute, 2774437, breakerDelivery, 30 * time.Minute},
 443			{"message already settled below the floor", 2774436, 30 * time.Minute, 2774400, breakerDelivery, 30 * time.Minute},
 444			{"message has not itself been failing long enough", 2774436, 30 * time.Minute, 2774437, breakerDelivery, 14 * time.Minute},
 445			{"message on its first delivery has had no retry at all", 2774436, 30 * time.Minute, 2774437, 1, 30 * time.Minute},
 446			{"deliveries burned fast by crashes, not by the ladder", 2774436, 30 * time.Minute, 2774437, breakerDelivery, 68 * time.Millisecond},
 447		}
 448		for _, tt := range tests {
 449			t.Run(tt.name, func(t *testing.T) {
 450				r, pub := newTestRetry(t, nil)
 451				armFloor(r, tt.floorSeq, tt.age)
 452				armFailing(r, tt.msgSeq, tt.failingFor)
 453				msg := deliveredMsg(tt.msgSeq, tt.attempt)
 454	
 455				s, err := r.Settle(t.Context(), msg, "transient")
 456				if err != nil {
 457					t.Fatalf("Settle: %v", err)
 458				}
 459				if s.Outcome != OutcomeRetried {
 460					t.Fatalf("Settlement = %+v, want retried", s)
 461				}
 462				if s.BreakerTripped {
 463					t.Error("Settlement reports a trip the conjunction should have refused")
 464				}
 465				if msg.Acked || msg.Termed {
 466					t.Errorf("message acked=%v termed=%v, want it left on the ladder", msg.Acked, msg.Termed)
 467				}
 468				if len(pub.captured()) != 0 {
 469					t.Error("dead-lettered a message the breaker must hold off on")
 470				}
 471			})
 472		}
