 521	// TestBreakerIsSelectiveUnderAMassTransient is the scenario that separates a
 522	// poison-message remedy from a mass dead-lettering engine, and the reason the
 523	// breaker rations itself.
 524	//
 525	// entiredb is down for an hour. Every message in flight fails, the floor is
 526	// stalled, and every one of them satisfies the breaker's conditions: above
 527	// the floor, failing longer than the threshold, past MinDeliveries. Left
 528	// unrationed the breaker would empty the consumer into the DLQ — which is
 529	// precisely the outcome a short ladder would produce, and therefore precisely
 530	// what the breaker exists to avoid. It must claim ONE message per stall
 531	// window instead.
 532	func TestBreakerIsSelectiveUnderAMassTransient(t *testing.T) {
 533		r, pub := newTestRetry(t, nil)
 534		base := time.Now()
 535		now := base
 536		r.clock = func() time.Time { return now }
 537		mon := r.cfg.Monitor
 538		floor := uint64(1000)
 539		armStall(mon, floor, 30*time.Minute)
 540	
 541		// 200 distinct messages, all failing for well over the threshold.
 542		settleAll := func() int {
 543			acked := 0
 544			for i := range uint64(200) {
 545				seq := floor + 1 + i
 546				armFailing(r, seq, 40*time.Minute)
 547				r.clock = func() time.Time { return now }
 548				msg := deliveredMsg(seq, breakerDelivery)
 549				if _, err := r.Settle(t.Context(), msg, "entiredb unavailable"); err != nil {
 550					t.Fatalf("Settle(seq %d): %v", seq, err)
 551				}
 552				if msg.Acked {
 553					acked++
 554				}
 555			}
 556			return acked
 557		}
 558	
 559		if n := settleAll(); n != 1 {
 560			t.Fatalf("%d of 200 messages dead-lettered in one stall window, want exactly 1", n)
 561		}
 562	
 563		// The claim did not move the floor — it was aimed at a message that was
 564		// not the blocker. The next window opens one FloorAge later, not sooner.
 565		now = base.Add(mon.FloorAge() - time.Second)
 566		armStall(mon, floor, 30*time.Minute)
 567		r.clock = func() time.Time { return now }
 568		if n := settleAll(); n != 0 {
 569			t.Errorf("%d further dead-letters inside the same window, want 0", n)
 570		}
 571		now = base.Add(mon.FloorAge() + time.Second)
 572		armStall(mon, floor, 30*time.Minute)
 573		r.clock = func() time.Time { return now }
 574		if n := settleAll(); n != 1 {
 575			t.Errorf("%d dead-letters in the next window, want exactly 1", n)
 576		}
 577	
 578		if got := len(pub.captured()); got != 2 {
 579			t.Errorf("captured %d messages across two windows, want 2", got)
 580		}
 581	}
