 309	// TestSettleBreakerDeadLettersThroughAStall is the ENT-1535 remedy, and the
 310	// regression test for the filtered-consumer defect: the message sits at a
 311	// stream sequence far above the ack floor, exactly as a poison event does when
 312	// non-matching subjects sit between it and the floor. An identification rule
 313	// keyed on floor+1 misses it (measured against a live server: floor 2, blocker
 314	// at stream 6); the conjunction does not.
 315	func TestSettleBreakerDeadLettersThroughAStall(t *testing.T) {
 316		var got Settlement
 317		r, pub := newTestRetry(t, func(c *RetryConfig) {
 318			c.OnSettle = func(_ context.Context, _ jetstream.Msg, s Settlement) { got = s }
 319		})
 320		armFloor(r, 2774436, 16*time.Minute)
 321		armFailing(r, 2774600, 16*time.Minute)
 322		msg := deliveredMsg(2774600, breakerDelivery) // 164 sequences above the floor
 323	
 324		s, err := r.Settle(t.Context(), msg, "re-queuing: update")
 325		if err != nil {
 326			t.Fatalf("Settle: %v", err)
 327		}
 328		if s.Outcome != OutcomeDeadLettered || s.Cause != CauseFloorAge {
 329			t.Fatalf("Settlement = %+v, want dead_lettered/floor_age", s)
 330		}
 331		if !s.BreakerTripped || !s.Captured {
 332			t.Errorf("Settlement = %+v, want the trip and the capture both reported", s)
 333		}
 334		if s.FailingFor != 16*time.Minute {
 335			t.Errorf("FailingFor = %s, want the 16m0s actually observed", s.FailingFor)
 336		}
 337		if !msg.Acked {
 338			t.Error("blocker not Acked; the ack floor stays pinned")
 339		}
 340		if msg.Termed {
 341			t.Error("blocker Termed; a Term does not settle the message (ENT-1492)")
 342		}
 343		if len(msg.NakDelays) != 0 || msg.Naks != 0 {
 344			t.Errorf("blocker also naked (%d delayed, %d plain), want none", len(msg.NakDelays), msg.Naks)
 345		}
 346		if s.Floor != 2774436 || s.FloorAge != 16*time.Minute {
 347			t.Errorf("Settlement floor state = %d/%s, want 2774436/16m0s", s.Floor, s.FloorAge)
 348		}
 349		if got != s {
 350			t.Errorf("OnSettle saw %+v, want %+v", got, s)
 351		}
 352	
 353		captured := pub.captured()
 354		if len(captured) != 1 {
 355			t.Fatalf("captured %d messages, want 1", len(captured))
 356		}
 357		c := captured[0]
 358		if c.Subject != "repo.refs.dlq" {
 359			t.Errorf("DLQ subject = %q, want repo.refs.dlq", c.Subject)
 360		}
 361		if string(c.Data) != "ref-event" {
 362			t.Errorf("DLQ payload = %q, want the raw message", c.Data)
 363		}
 364		if c.Header.Get("X-Entire-Repo") != "01KWHDFJ0C575CRVF18DPVSQW0" {
 365			t.Error("DLQ copy lost the original headers")
 366		}
 367		if reason := c.Header.Get(natsmsg.DLQReasonHeader); !strings.HasPrefix(reason, string(CauseFloorAge)+": ") {
 368			t.Errorf("DLQ reason = %q, want it prefixed with the cause", reason)
 369		}
 370		if c.Header.Get(natsmsg.DLQStreamSeqHeader) != "2774600" {
 371			t.Errorf("DLQ stream seq = %q, want 2774600", c.Header.Get(natsmsg.DLQStreamSeqHeader))
 372		}
 373	}
