 475	// TestBreakerMeasuresFailureTimeRatherThanInferringIt is the regression test
 476	// for the delivery-count inference. JetStream increments NumDelivered on
 477	// AckWait expiry too — a panicking handler, a killed pod, an eviction under
 478	// MaxAckPending — so a message can reach delivery 4 in milliseconds without
 479	// ever having served a ladder rung. Scoring those as three 5-minute rungs
 480	// would dead-letter a message that had barely arrived, on the strength of a
 481	// stall it had nothing to do with, and would break the "late, never early"
 482	// guarantee outright.
 483	func TestBreakerMeasuresFailureTimeRatherThanInferringIt(t *testing.T) {
 484		r, pub := newTestRetry(t, nil)
 485		base := time.Now()
 486		now := base
 487		r.clock = func() time.Time { return now }
 488		armStall(r.cfg.Monitor, 2774436, 30*time.Minute) // an OLD stall, from something else
 489	
 490		// Four crash-deliveries of a freshly arrived message, 68ms apart in total.
 491		msg := deliveredMsg(2774437, 0)
 492		for n := 1; n <= 4; n++ {
 493			now = base.Add(time.Duration(n) * 17 * time.Millisecond)
 494			msg = deliveredMsg(2774437, n)
 495			s, err := r.Settle(t.Context(), msg, "handler panicked")
 496			if err != nil {
 497				t.Fatalf("Settle(delivery %d): %v", n, err)
 498			}
 499			if s.BreakerTripped {
 500				t.Fatalf("delivery %d: breaker tripped on a message failing for %s; the ladder inference would have scored it %s",
 501					n, s.FailingFor, 3*5*time.Minute)
 502			}
 503		}
 504		if msg.Acked || len(pub.captured()) != 0 {
 505			t.Fatal("a message failing for 68ms was dead-lettered during an unrelated stall")
 506		}
 507	
 508		// Same message, same delivery count, once it really has been failing that
 509		// long: now it is a legitimate quarantine.
 510		now = base.Add(16 * time.Minute)
 511		aged := deliveredMsg(2774437, 4)
 512		s, err := r.Settle(t.Context(), aged, "still failing")
 513		if err != nil {
 514			t.Fatalf("Settle: %v", err)
 515		}
 516		if !s.BreakerTripped || !aged.Acked {
 517			t.Errorf("Settlement = %+v; want the trip once the measured clock reached the threshold", s)
 518		}
 519	}
