 583	// TestBreakerClearsSuccessiveFloorHolders: the flip side of the rationing.
 584	// When a claim DOES move the ack floor it was the blocker, so the next one
 585	// must not have to wait out a window — successive floor-holders drain as fast
 586	// as the stall clock re-arms, which is what makes the breaker a remedy rather
 587	// than a rate limiter.
 588	func TestBreakerClearsSuccessiveFloorHolders(t *testing.T) {
 589		r, pub := newTestRetry(t, nil)
 590		now := time.Now()
 591		r.clock = func() time.Time { return now }
 592		mon := r.cfg.Monitor
 593	
 594		for i, floor := range []uint64{1000, 1001, 1002} {
 595			armStall(mon, floor, 30*time.Minute) // floor advanced after the last claim
 596			seq := floor + 1
 597			armFailing(r, seq, 40*time.Minute)
 598			r.clock = func() time.Time { return now }
 599			msg := deliveredMsg(seq, breakerDelivery)
 600			if _, err := r.Settle(t.Context(), msg, "poison"); err != nil {
 601				t.Fatalf("Settle: %v", err)
 602			}
 603			if !msg.Acked {
 604				t.Fatalf("blocker %d not dead-lettered; a moved floor must re-arm the breaker at once", i+1)
 605			}
 606		}
 607		if got := len(pub.captured()); got != 3 {
 608			t.Errorf("captured %d successive floor-holders, want 3", got)
 609		}
 610	}
