   309	// TestSettleBreakerDeadLettersThroughAStall is the ENT-1535 remedy, and the
   310	// regression test for the filtered-consumer defect: the message sits at a
   311	// stream sequence far above the ack floor, exactly as a poison event does when
   312	// non-matching subjects sit between it and the floor. An identification rule
   313	// keyed on floor+1 misses it (measured against a live server: floor 2, blocker
   314	// at stream 6); the conjunction does not.
   315	func TestSettleBreakerDeadLettersThroughAStall(t *testing.T) {
   316		var got Settlement
   317		r, pub := newTestRetry(t, func(c *RetryConfig) {
