   652	// TestObserveFloorRestartsTheClockWhenTheFloorMoves: an advancing floor —
   653	// however slowly — is not a stall, and re-observing the same stalled floor
   654	// must not restart the clock either.
   655	func TestObserveFloorRestartsTheClockWhenTheFloorMoves(t *testing.T) {
   656		r, _ := newTestRetry(t, nil)
