   661		r.cfg.Monitor.observeFloor(100, 200, base)
   662		now = base.Add(10 * time.Minute)
   663		r.cfg.Monitor.observeFloor(100, 200, now) // same stall: the clock keeps running
   664		if _, age, _ := r.cfg.Monitor.FloorStall(); age != 10*time.Minute {
   665			t.Fatalf("age after re-observing the same floor = %s, want 10m0s", age)
   666		}
   667	
   668		r.cfg.Monitor.observeFloor(101, 200, now) // floor advanced: clock restarts
   669		floor, age, ok := r.cfg.Monitor.FloorStall()
   670		if !ok || floor != 101 || age != 0 {
   671			t.Fatalf("after the floor moved: floor=%d age=%s ok=%v, want 101/0s/true", floor, age, ok)
   672		}
