   674		// And the breaker is disarmed again for the new floor.
   675		msg := deliveredMsg(102, 2)
   676		if _, err := r.Settle(t.Context(), msg, "transient"); err != nil {
   677			t.Fatalf("Settle: %v", err)
   678		}
