   394	// logCapture is a thread-safe slog.Handler that counts messages, so a test
   395	// can assert a log line is emitted once per stationary period rather than
   396	// once per delivery.
   397	type logCapture struct {
   398		mu   sync.Mutex
   399		msgs []string
   400	}
   401	
   402	func (h *logCapture) Enabled(context.Context, slog.Level) bool { return true }
   403	
   404	func (h *logCapture) Handle(_ context.Context, r slog.Record) error {
   405		h.mu.Lock()
   406		h.msgs = append(h.msgs, r.Message)
   407		h.mu.Unlock()
   408		return nil
   409	}
   410	
   411	func (h *logCapture) WithAttrs([]slog.Attr) slog.Handler { return h }
   412	func (h *logCapture) WithGroup(string) slog.Handler      { return h }
   413	
   414	func (h *logCapture) snapshot() []string {
   415		h.mu.Lock()
   416		defer h.mu.Unlock()
   417		return slices.Clone(h.msgs)
   418	}
   419	
   420	func (h *logCapture) count(msg string) int {
   421		n := 0
   422		for _, m := range h.snapshot() {
   423			if m == msg {
   424				n++
   425			}
   426		}
   427		return n
   428	}
