   458				}
   459				if s.Outcome != OutcomeRetried {
   460					t.Fatalf("Settlement = %+v, want retried", s)
   461				}
   462				if s.BreakerTripped {
   463					t.Error("Settlement reports a trip the conjunction should have refused")
   464				}
   465				if msg.Acked || msg.Termed {
   466					t.Errorf("message acked=%v termed=%v, want it left on the ladder", msg.Acked, msg.Termed)
   467				}
   468				if len(pub.captured()) != 0 {
   469					t.Error("dead-lettered a message the breaker must hold off on")
   470				}
   471			})
   472		}
