   684	// TestObserveFloorIgnoresACaughtUpConsumer is the false positive that makes
   685	// the difference between a poison remedy and a message shredder: a quiet
   686	// consumer's floor sits still because NOTHING ARRIVED, not because anything
   687	// is stuck. Crediting the next message to arrive with that idle time would
   688	// dead-letter it on its second delivery. The stall clock therefore runs only
   689	// while the consumer has delivered past its own floor, and starts when the
   690	// gap opens — not when the floor last moved.
   691	func TestObserveFloorIgnoresACaughtUpConsumer(t *testing.T) {
   692		r, pub := newTestRetry(t, nil)
   693		base := time.Now()
   694		now := base
   695		r.cfg.Monitor.clock = func() time.Time { return now }
   696	
   697		// Four idle hours, fully caught up: floor stationary, but not stalled.
   698		r.cfg.Monitor.observeFloor(100, 100, base)
   699		now = base.Add(4 * time.Hour)
   700		r.cfg.Monitor.observeFloor(100, 100, now)
   701		if _, age, stalled := r.cfg.Monitor.FloorStall(); stalled {
   702			t.Fatalf("a caught-up consumer reported as stalled for %s", age)
   703		}
   704	
   705		// A message finally arrives and fails its way to breaker eligibility. The
   706		// breaker must still not fire: the stall clock starts now, not four hours ago.
   707		r.cfg.Monitor.observeFloor(100, 101, now)
   708		msg := deliveredMsg(101, breakerDelivery)
   709		if _, err := r.Settle(t.Context(), msg, "transient"); err != nil {
   710			t.Fatalf("Settle: %v", err)
   711		}
   712		if msg.Acked || len(pub.captured()) != 0 {
   713			t.Fatal("breaker dead-lettered a message credited with the consumer's idle time")
   714		}
   715	
   716		// Once the gap has genuinely persisted past the threshold, it fires.
   717		now = now.Add(16 * time.Minute)
   718		armFailing(r, 101, 16*time.Minute)
   719		blocker := deliveredMsg(101, breakerDelivery)
   720		if _, err := r.Settle(t.Context(), blocker, "re-queuing: update"); err != nil {
   721			t.Fatalf("Settle: %v", err)
   722		}
   723		if !blocker.Acked || len(pub.captured()) != 1 {
   724			t.Error("breaker did not fire on a stall that really had persisted")
   725		}
   726	}
